#include <iostream>
#include <utility>

int main() {
    int width = 4, height = 3, depth = 2;
    std::cout << width << ' ' << height << ' ' << depth << '\n';

    std::swap(width, depth);
    std::cout << width << ' ' << height << ' ' << depth << '\n';

    width = height = depth = 1;
    std::cout << width << ' ' << height << ' ' << depth << '\n';
    return 0;
}

