practice.solution:
#include <iostream>
#include <utility>

int main() {
    int first = 70, second = 85, third = 92;
    std::cout << first << ' ' << second << ' ' << third << '\n';

    std::swap(first, third);
    std::cout << first << ' ' << second << ' ' << third << '\n';

    first = second = third = 0;
    std::cout << first << ' ' << second << ' ' << third << '\n';
    return 0;
}
